 const invoiceLines=unique(t.invoice_lines,r=>identity(r.line_id,"invoice line ID"),"invoice line"),invoiceCurrencies=new Map();
 for(const r of invoiceLines.values()){need(jobs.has(r.job_id),"Invoice references unknown job");identity(r.invoice_id,"invoice ID");currency(r.currency);need(r.currency===jobs.get(r.job_id)[0].currency,"Invoice currency differs from job");if(invoiceCurrencies.has(r.invoice_id))need(invoiceCurrencies.get(r.invoice_id)===r.currency,"Invoice spans currencies");invoiceCurrencies.set(r.invoice_id,r.currency);r._amount=money(r.amount_minor,"invoice amount",true);r._time=stamp(r.issued_at,"invoice issued_at");text(r.description,"invoice description");}
