  r._amount=money(r.amount_minor,"allocation amount");need(r._amount>0n,"Allocation amount must be positive");r._time=stamp(r.authorized_at,"allocation authorized_at");need(r._time>=p._time,"Allocation precedes transaction");
  if(r.invoice_id)need(t.invoice_lines.some(x=>x.invoice_id===r.invoice_id&&x.job_id===r.job_id&&x.currency===p.currency),"Allocation invoice must belong to this job/currency");
  text(r.authorization,"allocation authorization");
