 for(const r of states.values()){need(pools.has(r.pool_id),"Status references unknown pool");need(["active","paused","inactive"].includes(r.status),"Invalid pool status");r._effective=stamp(r.effective_at,"pool status effective_at");r._time=stamp(r.observed_at,"pool status observed_at");text(r.authorization,"pool state authorization");}
 const stateMoments=new Map();for(const r of states.values()){const k=canonical([r.pool_id,r._effective,r._time]);const old=stateMoments.get(k);need(!old||old.status===r.status,"Conflicting pool status at the same effective and observed instant");stateMoments.set(k,r);}
 const occurrences=unique(t.expected_visits,r=>identity(r.occurrence_id,"occurrence ID"),"expected visit");
 for(const r of occurrences.values()){need(pools.has(r.pool_id),"Expected visit references unknown pool");identity(r.series_id,"source recurring series");interval(r,"due_start_at","due_end_at","expected visit");r._time=stamp(r.recorded_at,"expected visit recorded_at");need(["expected","waived"].includes(r.status),"Expected visit state must be expected or waived");text(r.authorization,"expected visit authority");}
 const stops=unique(t.route_stops,r=>identity(r.stop_id,"route stop ID"),"route stop"),revisionStops=new Set();
 for(const r of stops.values()){const j=revisions.get(r.revision_id);need(j,"Stop references unknown booking revision");identity(r.route_id,"source route ID");need(/^[1-9][0-9]{0,8}$/.test(r.stop_sequence),"Stop sequence must be a positive integer");r._sequence=Number(r.stop_sequence);r._time=stamp(r.recorded_at,"stop recorded_at");need(r._time>=j._time,"Stop record predates referenced booking revision");need(!revisionStops.has(r.revision_id),"A booking revision has more than one planned route-stop record");revisionStops.add(r.revision_id);if(r.occurrence_id){const o=occurrences.get(r.occurrence_id);need(o&&o.pool_id===j.pool_id,"Stop occurrence must belong to same pool");}}
 const services=unique(t.service_versions,r=>identity(r.service_version_id,"service version ID"),"service version"),serviceJobs=new Map();
 for(const r of services.values()){
  const j=revisions.get(r.revision_id);need(j&&j.job_id===r.job_id,"Service record must bind exact same-job booking revision");
  need(/^[1-9][0-9]{0,8}$/.test(r.version),"Positive service version integer required");r._version=Number(r.version);r._captured=stamp(r.captured_at,"service captured_at");r._time=stamp(r.observed_at,"service observed_at");need(r._captured<=r._time&&j._time<=r._captured,"Service capture/observation chronology differs");
  need(["draft","final","voided"].includes(r.status),"Invalid service record state");try{r._work=JSON.parse(r.work_json);}catch{throw Error("Invalid original work JSON");}need(plain(r._work),"Service work JSON must be an object");text(r.customer_notes,"customer notes",100000,true);text(r.internal_notes,"internal notes",100000,true);text(r.authorization,"service record authority");if(!serviceJobs.has(r.job_id))serviceJobs.set(r.job_id,[]);serviceJobs.get(r.job_id).push(r);
 }
 for(const rows of serviceJobs.values()){rows.sort((a,b)=>a._version-b._version);for(let i=0;i<rows.length;i++){const r=rows[i],p=rows[i-1];need(p?r._version>p._version&&r.previous_version_id===p.service_version_id&&r._time>p._time:!r.previous_version_id,"Service versions require a complete ordered predecessor chain");}}
 const readings=unique(t.readings,r=>identity(r.reading_id,"reading ID"),"reading");
 for(const r of readings.values()){need(services.has(r.service_version_id),"Reading references unknown service version");for(const k of ["analyte","value_text","unit","method"])text(r[k],"original reading "+k,2000);r._measured=stamp(r.measured_at,"reading measured_at");r._time=stamp(r.observed_at,"reading observed_at");need(r._measured<=r._time,"Reading observed before measurement");}
 const media=unique(t.media,r=>identity(r.media_id,"media ID"),"media");
 for(const r of media.values()){need(services.has(r.service_version_id),"Media references unknown service version");text(r.source_reference,"original media reference",10000);need(!r.artifact_sha256||/^[a-f0-9]{64}$/.test(r.artifact_sha256),"Media digest must be blank or lowercase SHA-256");r._captured=stamp(r.captured_at,"media captured_at");r._time=stamp(r.observed_at,"media observed_at");need(r._captured<=r._time,"Media observed before capture");text(r.caption,"media caption",10000,true);}
