 function members(raw,label,map,version){let ids;try{ids=JSON.parse(raw);}catch{throw Error("Invalid "+label+" JSON");}need(Array.isArray(ids)&&ids.length<=20000&&new Set(ids).size===ids.length,"Report member IDs must be distinct complete arrays");for(const id of ids){identity(id,label);need(map.get(id)?.service_version_id===version,"Report member belongs to another service version");}return ids;}
 for(const r of reports.values()){const v=services.get(r.service_version_id);need(v&&v.job_id===r.job_id,"Report must bind exact same-job service version");r._readings=members(r.reading_ids_json,"reading IDs",readings,r.service_version_id);r._media=members(r.media_ids_json,"media IDs",media,r.service_version_id);need(/^[a-f0-9]{64}$/.test(r.artifact_sha256),"Report needs source-reported SHA-256");r._created=stamp(r.created_at,"report created_at");r._time=stamp(r.observed_at,"report observed_at");need(r._created>=v._captured&&r._time>=r._created,"Report capture/observation chronology differs");for(const id of r._readings)need(readings.get(id)._measured<=r._created,"Report includes reading measured after creation");for(const id of r._media)need(media.get(id)._captured<=r._created,"Report includes media captured after creation");}
