 for(const r of deliveries.values()){const report=reports.get(r.report_id);need(report,"Delivery references unknown report");text(r.recipient,"actual report recipient",2000);text(r.channel,"actual report channel",500);r._submitted=stamp(r.submitted_at,"delivery submitted_at");r._time=stamp(r.observed_at,"delivery observed_at");need(r._submitted>=report._created&&r._time>=r._submitted,"Report delivery chronology differs");text(r.authorization,"delivery authority");}
 const events=unique(t.delivery_events,r=>identity(r.event_id,"delivery event ID"),"delivery event"),deliveryEvents=new Map();
 for(const r of events.values()){const d=deliveries.get(r.delivery_id);need(d,"Delivery event references unknown delivery");need(["sent","delivered","failed","bounced","acknowledged"].includes(r.kind),"Invalid delivery outcome");r._occurred=stamp(r.occurred_at,"delivery event occurred_at");r._time=stamp(r.observed_at,"delivery event observed_at");need(r._occurred>=d._submitted&&r._time>=r._occurred,"Delivery event chronology differs");text(r.evidence_reference,"actual delivery evidence",10000);if(!deliveryEvents.has(r.delivery_id))deliveryEvents.set(r.delivery_id,[]);deliveryEvents.get(r.delivery_id).push(r);}
 const periods=unique(t.billing_periods,r=>identity(r.period_id,"billing period ID"),"billing period");
 for(const r of periods.values()){interval(r,"start_at","end_at","billing period");need(r._end-r._start<=35*86400000,"Declare one monthly comparison period");r._counted=stamp(r.counted_at,"billing counted_at");r._time=stamp(r.observed_at,"billing observed_at");need(r._counted>=r._start&&r._time>=r._counted,"Billing observation/count chronology differs");currency(r.currency);r._platform=money(r.platform_minor,"platform fee");r._perPool=money(r.per_pool_minor,"per-pool fee");need(["full_month","provided_prorated"].includes(r.rate_basis),"Use full_month or provided_prorated source rates");text(r.proration_reference,"source proration",10000,r.rate_basis!=="provided_prorated");text(r.rule_reference,"source billing rule",10000);let excluded;try{excluded=JSON.parse(r.excluded_statuses_json);}catch{throw Error("Invalid excluded pool status JSON");}need(Array.isArray(excluded)&&new Set(excluded).size===excluded.length&&excluded.every(x=>["active","paused","inactive"].includes(x)),"Declare explicit excluded pool statuses");r._excluded=excluded;}
 return{pools,states,occurrences,stops,services,serviceJobs,readings,media,reports,deliveries,events,deliveryEvents,periods};
